*/
scwin.fnOrder = async function (mode, stat) {
    /* sdd-asis-lifecycle:begin fnOrder — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent("dma_fnDownloadReq").set("orderMode", mode);
    $c.util.getComponent("dma_fnDownloadReq").set("orderStat", stat);
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    await scwin.fnSearch();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearch
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearch = async function () {
    /* sdd-asis-lifecycle:begin fnSearch — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const searchForm = $("#searchForm");
    if (!$c.date.isDate(($c.util.getComponent("cal_fromDate").getValue() || ''))) {
        await $c.win.alert("시작일자 형식이 틀립니다");
        return;
    }
    if (!$c.date.isDate(($c.util.getComponent("cal_toDate").getValue() || ''))) {
        await $c.win.alert("종료일자 형식이 틀립니다");
        00;
        return;
    }
    if (($c.util.getComponent("cal_fromDate").getValue() || '') !== "" && ($c.util.getComponent("cal_toDate").getValue() || '') !== "") {
        if (!($c.date.diffDate(($c.util.getComponent("cal_fromDate").getValue() || ''), ($c.util.getComponent("cal_toDate").getValue() || '')) < 0 ? (await $c.win.alert('조회 기간이 올바르지 않습니다. 시작일자가 종료일자보다 늦습니다.'), false) : true)) {
            return;
        }
    }
    if ($c.date.addYear($c.util.getComponent('cal_fromDate').getValue(), 3) < $c.date.addYear($c.util.getComponent('cal_toDate').getValue(), 0)) {
        await $c.win.alert("조회기간은  3년 이내만 가능합니다.");
        return;
    }
    if (($c.util.getComponent("ipt_submitOblgNm").getValue() || '') === '') {
        $c.util.getComponent("dma_fnDownloadReq").set("fssUnqNo", "");
    }
    if ($(document).find("select[id=ipt_currentPageSize]").val() != null) {
        $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", $(document).find("select[id=ipt_currentPageSize]").val());
    }
    $c.util.getComponent("dma_fnDownloadReq").set("method", "searchMiscCorpDisclsSub");
    $c.util.getComponent("dma_fnDownloadReq").set("forward", "misccorpdiscls_sub");
    await scwin.tx_fnSearch_ajaxsubmit();
    /* sdd-asis-lifecycle:end */
};


/**
